"@

Write-Host 'Ajout du choix de quantite sur Commander maintenant...' -ForegroundColor Cyan
Write-FileFromBase64 -RelativePath "components/order-form.tsx" -Base64Content $b64_0

Write-Host ""
Write-Host "Modification appliquee avec succes !" -ForegroundColor Green
Write-Host "Le client peut maintenant choisir la quantite souhaitee avant d'envoyer sa commande depuis la fiche produit." -ForegroundColor Green
Write-Host ""
$confirm = Read-Host "Voulez-vous faire git add / commit / push maintenant ? (o/n)"
if ($confirm -eq 'o' -or $confirm -eq 'O') {
    git add components/order-form.tsx
    git commit -m "Feat: ajoute le choix de la quantite dans le formulaire Commander maintenant"
    git push
    Write-Host "Pousse sur Git avec succes !" -ForegroundColor Green
} else {
    Write-Host "Pas de push. Vous pouvez le faire plus tard avec : git add . ; git commit -m '...' ; git push" -ForegroundColor Yellow
}
